{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill defines early warning signs as evidence of safety, health, or behavioral issues. This includes, but is not limited to, signs that a student is involved in or is a victim of harassment, intimidation, bullying, or cyberbullying; is making or receiving threats of violence; or shows signs of substance abuse, mental health issues, self-harm, or suicidal ideation.",
      "rationale": "Conveys the definition, its nonexclusive scope, and all listed categories."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It would require each local education agency (LEA) and public charter school to set up a computer-based system where teachers and school staff must enter \"early warning signs\" shown by students.",
      "rationale": "Identifies the covered schools, required system, and mandatory teacher and staff use. The summary separately explains the existing-system exemption."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Each LEA and charter school must also train every teacher and staff member to spot early warning signs and to enter data into the system.",
      "rationale": "Covers all required personnel and both training subjects. The later exemption expressly includes training."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The system would have to match the LEA's bullying policy, the School Discipline Act, and each school safety plan under the SAVE Act.",
      "rationale": "Conveys alignment with all three required policy, discipline, and safety frameworks; 'bullying policy' adequately identifies the LEA policy."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It would need a database that can receive and keep the entered student data.",
      "rationale": "Covers the database's required receipt and retention capabilities, with the preceding discussion identifying the data and its teacher and staff sources."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "It would also have to immediately notify the LEA's threat assessment team, or a designated charter school employee, whenever an early warning sign is entered for a student.",
      "rationale": "Identifies the notification trigger, immediate timing, and recipients for both LEAs and charter schools."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The people who get a notice must review it and any earlier notices for that student. They must then decide whether more action is needed to address the student's behavior.",
      "rationale": "Covers recipients' review of current and previous notices and their further-action determination. The summary separately exempts qualifying existing systems from notice review."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Each LEA and charter school would have to send the Department of Education an annual report covering the prior school year. It would give the total number of early warning signs entered.",
      "rationale": "Includes the reporting entities, recipient, annual frequency, reporting period, and total entry count."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "It would break that number down by teachers (by grade level and subject taught) and by other staff (by position, assignment, and duties).",
      "rationale": "Includes the teacher-versus-staff breakdown and all required further disaggregation categories."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "It would give the number of students with more than one sign and the number of signs for each of those students.",
      "rationale": "Covers both the count of students with multiple entries and each such student's entry count."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "It would also give a general description of the types of signs and of the actions taken in response. Reports may not include details that could identify a student.",
      "rationale": "Covers both descriptions and the identification prohibition, but does not convey that responsive actions must be described for each entered warning sign."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Reports may not include details that could identify a student.",
      "rationale": "Conveys the report-wide prohibition on student-identifying information."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "They must follow FERPA, section 10-7-504, the Data Accessibility, Transparency, and Accountability Act, and other relevant privacy laws.",
      "rationale": "Includes every named privacy authority and the requirement to follow other relevant privacy laws."
    },
    {
      "proposition_id": "P14",
      "status": "full",
      "summary_quote": "If the commissioner of education finds that an LEA or charter school is not complying, the commissioner may withhold state funds, in an amount the commissioner decides, until it complies.",
      "rationale": "Covers the noncompliance finding, discretionary withholding, commissioner-determined amount, and duration until compliance."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "The requirements for the system, training, and review of notices would not apply to an LEA or charter school that already had a system for documenting early warning signs before July 1, 2026, as long as it continuously maintains and uses that system.",
      "rationale": "States the exemption's covered requirements, qualifying system, cutoff date, and continuous maintenance and use condition. Its limited scope leaves the separately stated reporting requirements applicable."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "The bill takes effect July 1, 2026.",
      "rationale": "States the effective date exactly."
    }
  ]
}
